<script setup lang="ts">
import {ref,onMounted,computed,nextTick} from 'vue';import type {ModuleRecord} from '@/mocks/modules';import {ModuleService,StorageService} from '@/services';import {useAppStore} from '@/stores/app';import {useAuthStore} from '@/stores/auth';import {sanitizeHtml} from '@/utils/html';import {Save,Bold,Italic,Underline,List,ListOrdered,AlignLeft,AlignCenter,Undo2,Redo2,History,RotateCcw,Eye,FileText} from 'lucide-vue-next';
interface ChangeLog{id:number;method:'CREATE'|'UPDATE'|'PUBLISH'|'RESTORE';author:string;at:string;summary:string;explanation:string;snapshot:string}
const emit=defineEmits<{saved:[record:ModuleRecord]}>();const props=defineProps<{record:ModuleRecord}>(),app=useAppStore(),auth=useAuthStore(),editor=ref<HTMLElement>(),title=ref(props.record.name),category=ref(props.record.category),status=ref(props.record.status),tab=ref<'document'|'history'>('document'),wordCount=ref(0),savedHtml=ref(props.record.notes??'<h1>Procedimento técnico</h1><p>Descreva aqui o objetivo e as etapas do procedimento.</p><h2>Passo a passo</h2><ol><li>Primeira etapa do atendimento.</li><li>Validação do resultado.</li></ol>');const logKey=`knowledge:logs:${props.record.id}`;const logs=ref<ChangeLog[]>(StorageService.get(logKey,[{id:1,method:'CREATE',author:props.record.owner||'Lucas Almeida',at:props.record.updatedAt,summary:'Artigo criado',explanation:'CREATE — criou a primeira versão do documento na base de conhecimento.',snapshot:savedHtml.value}]));
const lastSaved=computed(()=>logs.value[0]?.at||props.record.updatedAt);function updateCount(){wordCount.value=(editor.value?.innerText.trim().match(/\S+/g)||[]).length}function format(command:string,value?:string){editor.value?.focus();document.execCommand(command,false,value);updateCount()}function addLog(method:ChangeLog['method'],summary:string,explanation:string,snapshot:string){logs.value.unshift({id:Date.now(),method,author:auth.user?.name||'Equipe de TI',at:new Date().toLocaleString('pt-BR'),summary,explanation,snapshot});StorageService.set(logKey,logs.value)}function save(publish=false){try{const html=sanitizeHtml(editor.value?.innerHTML??savedHtml.value);const changed=[];if(title.value!==props.record.name)changed.push('título');if(category.value!==props.record.category)changed.push('categoria');if(html!==savedHtml.value)changed.push('conteúdo');const items=ModuleService.list('knowledge').map(x=>x.id===props.record.id?{...x,name:title.value,category:category.value,status:publish?'Publicado':status.value,notes:html,updatedAt:new Date().toISOString()}:x);ModuleService.save('knowledge',items);emit('saved',items.find(x=>x.id===props.record.id)!);savedHtml.value=html;status.value=publish?'Publicado':status.value;addLog(publish?'PUBLISH':'UPDATE',publish?'Artigo publicado':`Alterações salvas: ${changed.join(', ')||'metadados'}`,publish?'PUBLISH — disponibilizou esta versão para consulta pelos técnicos.':'UPDATE — salvou uma nova versão do conteúdo e dos metadados do artigo.',html);app.toast(publish?'Artigo publicado':'Documento salvo',publish?'A nova versão está disponível.':'As alterações e o log foram armazenados localmente.')}catch(error){app.toast('Falha ao salvar',error instanceof Error?error.message:String(error),'error')}}async function restore(log:ChangeLog){if(!confirm('Restaurar o conteúdo desta versão?'))return;savedHtml.value=log.snapshot;tab.value='document';await nextTick();if(editor.value)editor.value.innerHTML=sanitizeHtml(log.snapshot);addLog('RESTORE',`Versão de ${log.at} restaurada`,'RESTORE — recuperou o conteúdo de uma versão anterior e criou um novo ponto no histórico.',log.snapshot);save()}
onMounted(()=>{if(editor.value)editor.value.innerHTML=sanitizeHtml(savedHtml.value);updateCount()})
</script>
<template><div class="mt-4 grid grid-cols-[minmax(0,1fr)_280px] gap-4"><section class="card overflow-hidden"><div class="flex items-center justify-between border-b px-4 py-3 dark:border-slate-700"><div class="flex rounded-md bg-slate-100 p-1 dark:bg-slate-900"><button class="rounded px-3 py-1.5 text-xs font-semibold" :class="tab==='document'?'bg-white shadow dark:bg-slate-700':''" @click="tab='document'"><FileText class="mr-1 inline size-3"/>Documento</button><button class="rounded px-3 py-1.5 text-xs font-semibold" :class="tab==='history'?'bg-white shadow dark:bg-slate-700':''" @click="tab='history'"><History class="mr-1 inline size-3"/>Histórico ({{logs.length}})</button></div><div class="text-[11px] text-slate-400">Último salvamento: {{lastSaved}}</div></div><div v-show="tab==='document'"><div class="grid grid-cols-[1fr_180px] gap-3 border-b p-4 dark:border-slate-700"><div><label class="label">Título do artigo</label><input v-model="title" class="field font-semibold"/></div><div><label class="label">Categoria</label><input v-model="category" class="field"/></div></div><div class="flex flex-wrap items-center gap-1 border-b bg-slate-50 px-4 py-2 dark:border-slate-700 dark:bg-slate-900"><select class="h-8 rounded border bg-white px-2 text-xs dark:bg-slate-800" @change="format('formatBlock',($event.target as HTMLSelectElement).value)"><option value="p">Texto normal</option><option value="h1">Título 1</option><option value="h2">Título 2</option><option value="h3">Título 3</option></select><span class="mx-1 h-6 w-px bg-slate-300"/><button v-for="[cmd,icon,label] in [['bold',Bold,'Negrito'],['italic',Italic,'Itálico'],['underline',Underline,'Sublinhado']]" :key="String(cmd)" class="rounded p-2 hover:bg-slate-200 dark:hover:bg-slate-700" :title="String(label)" @click="format(String(cmd))"><component :is="icon" class="size-4"/></button><span class="mx-1 h-6 w-px bg-slate-300"/><button class="rounded p-2 hover:bg-slate-200" title="Lista" @click="format('insertUnorderedList')"><List class="size-4"/></button><button class="rounded p-2 hover:bg-slate-200" title="Lista numerada" @click="format('insertOrderedList')"><ListOrdered class="size-4"/></button><button class="rounded p-2 hover:bg-slate-200" title="Alinhar à esquerda" @click="format('justifyLeft')"><AlignLeft class="size-4"/></button><button class="rounded p-2 hover:bg-slate-200" title="Centralizar" @click="format('justifyCenter')"><AlignCenter class="size-4"/></button><span class="mx-1 h-6 w-px bg-slate-300"/><button class="rounded p-2 hover:bg-slate-200" title="Desfazer" @click="format('undo')"><Undo2 class="size-4"/></button><button class="rounded p-2 hover:bg-slate-200" title="Refazer" @click="format('redo')"><Redo2 class="size-4"/></button></div><div class="min-h-[650px] bg-slate-200 p-8 dark:bg-slate-950"><article ref="editor" contenteditable spellcheck="true" class="knowledge-page mx-auto min-h-[590px] w-full max-w-[680px] bg-white px-8 py-14 text-slate-800 shadow-md outline-none" @input="updateCount"/></div><div class="flex items-center border-t px-4 py-2 text-[11px] text-slate-500 dark:border-slate-700"><span>Página 1 de 1</span><span class="ml-5">{{wordCount}} palavras</span><span class="ml-auto">Português (Brasil)</span></div></div><div v-show="tab==='history'" class="p-5"><div class="mb-4 rounded-md bg-blue-50 p-3 text-xs text-blue-800 dark:bg-blue-950 dark:text-blue-200"><b>Como os métodos funcionam:</b> CREATE registra a criação; UPDATE salva uma revisão; PUBLISH libera a versão; RESTORE recupera uma versão sem apagar o histórico.</div><div v-for="log in logs" :key="log.id" class="mb-3 grid grid-cols-[90px_1fr_auto] gap-3 rounded-lg border p-4 dark:border-slate-700"><span class="h-fit rounded px-2 py-1 text-center font-mono text-[10px] font-bold" :class="log.method==='PUBLISH'?'bg-emerald-50 text-emerald-700':log.method==='RESTORE'?'bg-amber-50 text-amber-700':log.method==='CREATE'?'bg-blue-50 text-blue-700':'bg-violet-50 text-violet-700'">{{log.method}}</span><div><b class="text-xs">{{log.summary}}</b><p class="mt-1 text-xs text-slate-500">{{log.explanation}}</p><div class="mt-2 text-[10px] text-slate-400">{{log.author}} · {{log.at}}</div></div><button class="btn btn-secondary !h-8" @click="restore(log)"><RotateCcw class="size-3"/>Restaurar</button></div></div></section><aside class="space-y-4"><div class="card p-4"><div class="flex items-center justify-between"><h3 class="text-sm font-bold">Publicação</h3><span class="rounded-full bg-emerald-50 px-2 py-1 text-[10px] font-bold text-emerald-700">{{status}}</span></div><p class="mt-3 text-xs leading-5 text-slate-500">Salve como revisão ou publique para disponibilizar o procedimento à equipe.</p><button class="btn btn-primary mt-4 w-full" @click="save(false)"><Save class="size-4"/>Salvar revisão</button><button class="btn btn-secondary mt-2 w-full" @click="save(true)"><Eye class="size-4"/>Publicar artigo</button></div><div class="card p-4"><h3 class="text-sm font-bold">Metadados</h3><div class="mt-3 text-[11px] text-slate-500">Autor responsável</div><b class="text-xs">{{record.owner}}</b><div class="mt-3 text-[11px] text-slate-500">Identificador</div><b class="font-mono text-xs">KB-{{String(record.id).padStart(4,'0')}}</b><div class="mt-3 text-[11px] text-slate-500">Visualizações</div><b class="text-xs">{{record.info}}</b></div></aside></div></template>
<style scoped>.knowledge-page :deep(h1){font-size:28px;font-weight:700;margin:0 0 20px}.knowledge-page :deep(h2){font-size:20px;font-weight:700;margin:24px 0 10px}.knowledge-page :deep(h3){font-size:16px;font-weight:700;margin:18px 0 8px}.knowledge-page :deep(p){font-size:14px;line-height:1.75;margin:9px 0}.knowledge-page :deep(ol),.knowledge-page :deep(ul){margin:10px 0;padding-left:24px}.knowledge-page :deep(ol){list-style:decimal}.knowledge-page :deep(ul){list-style:disc}</style>
